#include "protocol.h"
uint16_t cs_crc16(const uint8_t *d,size_t n){uint16_t c=0xffffu;size_t i;unsigned b;if(!d&&n)return 0;for(i=0;i<n;i++){c^=(uint16_t)d[i]<<8;for(b=0;b<8;b++)c=(c&0x8000u)?(uint16_t)((c<<1)^0x1021u):(uint16_t)(c<<1);}return c;}
static void p16(uint8_t*p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}static void p32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}static uint16_t g16(const uint8_t*p){return(uint16_t)(p[0]|((uint16_t)p[1]<<8));}static uint32_t g32(const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
int cs_encode(const cs_frame_t*f,uint8_t*o,size_t cap){if(!f||!o||cap<CS_FRAME_SIZE||f->version!=CS_VERSION||f->state>CS_ACTIVE)return-1;o[0]=0xc5;o[1]=0x51;o[2]=f->version;o[3]=f->type;p32(o+4,f->node_id);p16(o+8,f->sequence);o[10]=f->state;o[11]=f->flags;p16(o+12,f->sample_ma);p16(o+14,cs_crc16(o,14));return(int)CS_FRAME_SIZE;}
int cs_decode(const uint8_t*d,size_t n,cs_frame_t*f){if(!d||!f||n!=CS_FRAME_SIZE||d[0]!=0xc5||d[1]!=0x51||d[2]!=CS_VERSION||d[10]>CS_ACTIVE||g16(d+14)!=cs_crc16(d,14))return-1;f->version=d[2];f->type=d[3];f->node_id=g32(d+4);f->sequence=g16(d+8);f->state=d[10];f->flags=d[11];f->sample_ma=g16(d+12);return 0;}
